function roundTo(n, digits) {
  return Number(n.toFixed(digits));
}

function clamp(n, min, max) {
  return Math.min(Math.max(n, min), max);
}

console.log(roundTo(3.14159, 2));
console.log(clamp(15, 0, 10));
